import fs from "node:fs";
import path from "node:path";
import { test, expect } from "../../fixtures/test-base";
import { seedDenseWorkbench, DENSE_WORKLOAD } from "../../helpers/dense-workbench-fixture";
import { prepareDenseStream } from "../../helpers/dense-canonical-stream";
import { seedThreadPresentation } from "../task/threads-presentation-helpers";
import { dwell } from "../../helpers/causal-waits";

test("attributes file-link context updates in the retained production build", async ({
  testPage: page, apiClient: api, seedData: seed, backend,
}, info) => {
  test.setTimeout(600_000);
  const directory = path.resolve(process.cwd(), "../../.kandev/diagnostics/dense-workbench-performance");
  const output = path.join(directory, `context-attribution-${Date.now()}.json`);
  const report: Record<string, unknown> = {
    kind: "context-attribution; excluded from speed comparisons",
    assetsSha256: "9f2b7a961b623e0e4074fdfd0e253b10b65ccf979e110223af6b88b9121dbea8",
    workload: DENSE_WORKLOAD,
    source: "context-attribution-source.ts",
  };
  await page.setViewportSize({ width: 1470, height: 956 });
  await page.addInitScript(() => {
    const win = window as any;
    const stats = {
      active: false, commits: 0, providers: 0, valueChanges: 0,
      aliasIdentityChanges: 0, redundantValueChanges: 0,
      aliasSemanticChanges: 0, callbackChanges: 0, pathChanges: 0,
      groups: {} as Record<string, number>, renderers: [] as string[], errors: [] as string[],
    };
    const previous = new WeakMap<object, any>();
    const aliasKeys = new WeakMap<object, string>();
    const aliasKey = (value: object) => {
      let key = aliasKeys.get(value);
      if (key === undefined) { key = JSON.stringify(value); aliasKeys.set(value, key); }
      return key;
    };
    win.__reactContextAttribution = stats;
    win.__KANDEV_E2E_EXPOSE_STORE__ = true;
    win.__REACT_DEVTOOLS_GLOBAL_HOOK__ = {
      supportsFiber: true,
      renderers: new Map(),
      inject(renderer: any) {
        const id = this.renderers.size + 1;
        this.renderers.set(id, renderer);
        stats.renderers.push(renderer.version || "unknown");
        return id;
      },
      onCommitFiberRoot(_id: number, root: any) {
        try {
          const stack = [root.current];
          if (stats.active) stats.commits++;
          while (stack.length) {
            const fiber = stack.pop();
            if (!fiber) continue;
            if (fiber.child) stack.push(fiber.child);
            if (fiber.sibling) stack.push(fiber.sibling);
            const value = fiber.memoizedProps?.value;
            if (fiber.tag !== 10 || !value || !Array.isArray(value.fileRootAliases)) continue;
            const prior = previous.get(fiber) || (fiber.alternate && previous.get(fiber.alternate));
            const current = { value, aliases: value.fileRootAliases,
              key: aliasKey(value.fileRootAliases), path: value.worktreePath, callback: value.onOpenFile };
            previous.set(fiber, current);
            if (fiber.alternate) previous.set(fiber.alternate, current);
            if (!stats.active) { stats.providers++; continue; }
            if (!prior || prior.value === value) continue;
            stats.valueChanges++;
            if (prior.aliases !== current.aliases) stats.aliasIdentityChanges++;
            if (prior.key !== current.key) stats.aliasSemanticChanges++;
            if (prior.path !== current.path) stats.pathChanges++;
            if (prior.callback !== current.callback) stats.callbackChanges++;
            if (prior.key === current.key && prior.path === current.path && prior.callback === current.callback) {
              stats.redundantValueChanges++;
              let owner = fiber.return;
              while (owner && typeof owner.type !== "function") owner = owner.return;
              const name = owner?.type?.displayName || owner?.type?.name || "anonymous";
              stats.groups[name] = (stats.groups[name] || 0) + 1;
            }
          }
        } catch (error) {
          if (stats.errors.length < 10) stats.errors.push(String(error));
        }
      },
      onCommitFiberUnmount() {},
      onPostCommitFiberRoot() {},
    };
  });
  let stream: Awaited<ReturnType<typeof prepareDenseStream>> | undefined;
  try {
    const fixture = await seedDenseWorkbench(api, seed, true);
    report.fixture = fixture;
    await seedThreadPresentation(api, { layout: "grid", maxChats: 6, autoHideComposer: true });
    stream = await prepareDenseStream(api, seed, backend, fixture.threads.slice(0, 6), "context-attribution");
    await page.goto(`/threads?workspace=${seed.workspaceId}`);
    await expect(page.getByTestId("threads-board")).toBeVisible();
    for (const thread of fixture.threads.slice(0, 6)) {
      await expect(page.getByTestId(`thread-column-${thread.taskId}`)).toContainText(stream.warmup);
    }
    report.before = await page.evaluate(() => {
      const stats = (window as any).__reactContextAttribution;
      stats.active = true;
      return JSON.parse(JSON.stringify(stats));
    });
    expect((report.before as any).renderers.length).toBeGreaterThan(0);
    expect((report.before as any).providers).toBeGreaterThan(0);
    stream.release();
    await dwell(page, DENSE_WORKLOAD.durationMs, "clock-separation", "observe a fixed canonical stream for context attribution");
    await stream.waitForVisible(page);
    await stream.verify();
    report.after = await page.evaluate(() => {
      const stats = (window as any).__reactContextAttribution;
      stats.active = false;
      return JSON.parse(JSON.stringify(stats));
    });
    report.scheduledUpdates = stream.scheduledUpdates;
    report.verificationErrors = stream.verificationErrors;
    expect((report.after as any).errors).toEqual([]);
  } catch (error) {
    report.error = String(error);
    throw error;
  } finally {
    if (stream) await stream.finish();
    fs.writeFileSync(output, JSON.stringify(report, null, 2));
    await info.attach("context-attribution", { path: output, contentType: "application/json" });
  }
});

